using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, ai_command> ai_commandData;
        public ai_command Getai_commandConfig(int key)
        {
            return ConfigBinary.Require(ai_commandData, key, "ai_command");
        }
        private void Loadai_commandConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("ai_command"))
            {
                int count = r.ReadInt32();
                ai_commandData = new Dictionary<int, ai_command>(count);
                for (int i = 0; i < count; i++)
                {
                    ai_command row;
                    row.key = r.ReadInt32();
                    row.command = ConfigBinary.ReadString(r);
                    row.commandHelp = ConfigBinary.ReadString(r);
                    byte has2 = r.ReadByte();
                    row.home = has2 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    byte has3 = r.ReadByte();
                    row.lobby = has3 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    byte has4 = r.ReadByte();
                    row.battle = has4 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    row.param1Name = ConfigBinary.ReadString(r);
                    row.param1Type = ConfigBinary.ReadString(r);
                    row.param1Desc = ConfigBinary.ReadString(r);
                    row.param2Name = ConfigBinary.ReadString(r);
                    row.param2Type = ConfigBinary.ReadString(r);
                    row.param2Desc = ConfigBinary.ReadString(r);
                    row.param3Name = ConfigBinary.ReadString(r);
                    row.param3Type = ConfigBinary.ReadString(r);
                    row.param3Desc = ConfigBinary.ReadString(r);
                    ai_commandData.Add(row.key, row);
                }
            }
        }
    }
    public struct ai_command
    {
        public int key;  // 主键
        public string command;  // 主命令
        public string commandHelp;  // 主命令注释
        public bool? home;  // Home可用：1=可用，留空=不可用
        public bool? lobby;  // Lobby可用：1=可用，留空=不可用
        public bool? battle;  // Battle可用：1=可用，留空=不可用
        public string param1Name;  // 参数1
        public string param1Type;  // 参数1类型：int / float / bool / string / List<int>
        public string param1Desc;  // 参数1含义
        public string param2Name;  // 参数2
        public string param2Type;  // 参数2类型：int / float / bool / string / List<int>
        public string param2Desc;  // 参数2含义
        public string param3Name;  // 参数3
        public string param3Type;  // 参数3类型：int / float / bool / string / List<int>
        public string param3Desc;  // 参数3含义
    }
}
